 @Test void editingStudentCanKeepOrChangeAccommodationBed(){
  String account="bed-edit-"+UUID.randomUUID(),studentNo="B"+UUID.randomUUID().toString().substring(0,20);long id=management.saveUser(admin,null,Map.of("account",account,"studentNo",studentNo,"realName","Bed Edit","gender","MALE","roleCode","STUDENT","password","123456"));
  var beds=db.rows("SELECT bd.bed_id FROM bed bd JOIN dorm_room r ON r.room_id=bd.room_id JOIN building b ON b.building_id=r.building_id WHERE bd.management_status='AVAILABLE' AND b.gender_limit IN ('男生','混合') AND bd.bed_id NOT IN (SELECT bed_id FROM v_accommodation_current) ORDER BY bd.bed_id");
  long first=Input.id(beds.get(0).get("bed_id")),second=Input.id(beds.get(1).get("bed_id"));
  var edit=Map.<String,Object>of("account",account,"studentNo",studentNo,"realName","Bed Edit","roleCode","STUDENT","bedId",first);
  management.saveUser(admin,id,edit);long assignmentCount=db.count("SELECT COUNT(*) FROM accommodation_assignment WHERE student_id=?",id);
  management.saveUser(admin,id,edit);assertEquals(assignmentCount,db.count("SELECT COUNT(*) FROM accommodation_assignment WHERE student_id=?",id));
  management.saveUser(admin,id,Map.of("account",account,"studentNo",studentNo,"realName","Bed Edit","roleCode","STUDENT","bedId",second));
  assertEquals(second,Input.id(db.one("SELECT bed_id FROM v_accommodation_current WHERE student_id=?",id).get("bed_id")));
  assertEquals(1L,db.count("SELECT COUNT(*) FROM accommodation_assignment WHERE student_id=? AND check_out_date IS NULL",id));
 }
 @Test void exportTaskCanRunAndPendingTaskCanCancel(){long task=Input.id(tasks.create(admin,Map.of("taskType","EXPORT","businessType","users")).get("taskId"));assertEquals("WAITING",tasks.dataTask(admin,task).get("task_status"));tasks.runWaiting();assertEquals("SUCCESS",tasks.dataTask(admin,task).get("task_status"));assertEquals(1L,db.count("SELECT COUNT(*) FROM import_export_task_file WHERE task_id=? AND file_purpose='OUTPUT'",task));assertThrows(BizException.class,()->tasks.cancel(admin,task));long pending=Input.id(tasks.create(admin,Map.of("taskType","EXPORT","businessType","users")).get("taskId"));tasks.cancel(admin,pending);assertEquals("CANCELLED",tasks.dataTask(admin,pending).get("task_status"));assertEquals(403,assertThrows(BizException.class,()->tasks.dataTask(student,task)).status());}
 @Test void accommodationAssignmentRejectsBedsForAnotherGender(){
  String account="female-bed-"+UUID.randomUUID();long studentId=management.saveUser(admin,null,Map.of("account",account,"studentNo","G"+UUID.randomUUID().toString().substring(0,20),"realName","Female Student","gender","FEMALE","roleCode","STUDENT","password","123456"));
  long maleBed=Input.id(db.one("SELECT bd.bed_id FROM bed bd JOIN dorm_room r ON r.room_id=bd.room_id JOIN building b ON b.building_id=r.building_id WHERE b.gender_limit='男生' AND bd.management_status='AVAILABLE' AND bd.bed_id NOT IN (SELECT bed_id FROM v_accommodation_current) ORDER BY bd.bed_id LIMIT 1").get("bed_id"));
  assertThrows(BizException.class,()->management.assign(admin,Map.of("studentId",studentId,"bedId",maleBed)));
  assertEquals(0L,db.count("SELECT COUNT(*) FROM accommodation_assignment WHERE student_id=?",studentId));
 }
 @Test void staffCreationAndConfigurationStoreSelectedScopes(){
  long managerId=management.saveUser(admin,null,Map.of("account","scope-manager-"+UUID.randomUUID(),"employeeNo","M-"+UUID.randomUUID(),"realName","Scoped Manager","roleCode","DORM_MANAGER","password","123456","buildingId",3));
  long workerId=management.saveUser(admin,null,Map.of("account","scope-worker-"+UUID.randomUUID(),"employeeNo","R-"+UUID.randomUUID(),"realName","Scoped Worker","roleCode","REPAIRER","password","123456","buildingIds",List.of(1),"workTypeIds",List.of(1),"onDuty",true));
  assertEquals(1L,db.count("SELECT COUNT(*) FROM manager_building_scope WHERE manager_user_id=? AND building_id=3",managerId));
  assertEquals(1L,db.count("SELECT COUNT(*) FROM repairer_building_scope WHERE repairer_user_id=? AND building_id=1",workerId));
  assertEquals(1L,db.count("SELECT COUNT(*) FROM repairer_work_type WHERE repairer_user_id=? AND work_type_id=1",workerId));
  var config=management.config(admin);var worker=((List<Map<String,Object>>)config.get("workers")).stream().filter(x->Input.id(x.get("repairer_user_id"))==workerId).findFirst().orElseThrow();
  assertEquals("Scoped Worker",worker.get("real_name"));assertNotNull(worker.get("employee_no"));
 }
 Map<String,Object> body(){return new HashMap<>(Map.of("title","Integration repair","description","Socket broken","categoryId",2));}
 @Test void unassignedStudentCanReadEmptyAccommodation(){long id=management.saveUser(admin,null,Map.of("account","unassigned-"+UUID.randomUUID(),"studentNo","T"+UUID.randomUUID().toString().substring(0,20),"realName","New","gender","OTHER","roleCode","STUDENT","password","123456"));var user=new CurrentUser(id,"new","New","STUDENT");assertTrue(management.homes(user,false).isEmpty());assertTrue(management.roommates(user).isEmpty());assertTrue(management.roommates(student).stream().noneMatch(x->"A".equals(x.get("bed_no"))));}
 @Test void studentNumberIsRequiredUniqueAndSearchable(){Map<String,Object> data=new HashMap<>();data.put("account","numbered-"+UUID.randomUUID());data.put("realName","Numbered");data.put("roleCode","STUDENT");data.put("password","123456");assertThrows(BizException.class,()->management.saveUser(admin,null,data));String studentNo="S"+UUID.randomUUID().toString().substring(0,20);var complete=new HashMap<String,Object>(data);complete.put("studentNo",studentNo);complete.put("gender","FEMALE");long user=management.saveUser(admin,null,complete);assertEquals(1L,db.count("SELECT COUNT(*) FROM student WHERE student_id=? AND student_no=? AND student_name='Numbered' AND gender='FEMALE'",user,studentNo));assertEquals(1L,db.count("SELECT COUNT(*) FROM v_user_identity WHERE user_id=? AND real_name='Numbered'",user));assertEquals(0L,db.count("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='sys_user' AND column_name='real_name'"));var duplicate=new HashMap<String,Object>(data);duplicate.put("account","duplicate-"+UUID.randomUUID());duplicate.put("studentNo",studentNo);duplicate.put("gender","FEMALE");assertThrows(BizException.class,()->management.saveUser(admin,null,duplicate));var filtered=management.users(admin,Map.of("roleCode","STUDENT","studentNo",studentNo,"realName","Numbered"));assertEquals(1,filtered.size());assertEquals(user,Input.id(filtered.get(0).get("user_id")));}
 @Test void studentProfileUsesSharedPrimaryKeyAndBusinessForeignKeys(){assertEquals(0L,db.count("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='sys_user'"));assertEquals(1L,db.count("SELECT COUNT(*) FROM student s JOIN v_user_identity i ON i.user_id=s.student_id WHERE s.student_id=? AND i.real_name=s.student_name",student.id()));assertEquals(1L,db.count("SELECT COUNT(*) FROM person p JOIN student s ON s.student_id=p.person_id WHERE p.person_id=?",student.id()));assertEquals(3L,db.count("SELECT COUNT(*) FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND referenced_table_name='student' AND column_name='student_id' AND table_name IN ('accommodation_assignment','repair_order','stay_application')"));assertEquals(0L,db.count("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='repair_evaluation' AND column_name='student_id'"));long user=management.saveUser(admin,null,Map.of("account","role-change-"+UUID.randomUUID(),"studentNo","C"+UUID.randomUUID().toString().substring(0,20),"realName","Role Change","gender","OTHER","roleCode","STUDENT","password","123456"));assertThrows(BizException.class,()->management.saveUser(admin,user,Map.of("account","role-change","realName","Role Change","roleCode","ADMIN","password","")));assertEquals(1L,db.count("SELECT COUNT(*) FROM student WHERE student_id=?",user));assertEquals(1L,db.count("SELECT COUNT(*) FROM v_user_identity WHERE user_id=? AND role_code='STUDENT'",user));}
 @Test void academicStructureFlowsIntoStudentProfileAndFilters(){long department=management.academicResource(admin,"departments",null,Map.of("code","D-"+UUID.randomUUID(),"name","工程学院","enabled",true));long major=management.academicResource(admin,"majors",null,Map.of("departmentId",department,"code","M-"+UUID.randomUUID(),"name","软件工程","enabled",true));long classId=management.academicResource(admin,"classes",null,Map.of("majorId",major,"code","C-"+UUID.randomUUID(),"name","软件工程1班","enrollmentYear","2024","enabled",true));long id=management.saveUser(admin,null,Map.of("account","academic-"+UUID.randomUUID(),"studentNo","S"+UUID.randomUUID().toString().substring(0,20),"realName","Academic Student","gender","FEMALE","birthDate","2005-04-12","classId",classId,"enrollmentStatus","ENROLLED","roleCode","STUDENT","password","123456"));var rows=management.users(admin,Map.of("roleCode","STUDENT","departmentId",Long.toString(department),"majorId",Long.toString(major),"classId",Long.toString(classId),"enrollmentStatus","ENROLLED","keyword","Academic Student"));assertEquals(1,rows.size());assertEquals("工程学院",rows.get(0).get("department_name"));assertEquals("2024级",rows.get(0).get("grade"));var detail=management.userDetail(admin,id);assertEquals("软件工程1班",detail.get("class_name"));assertEquals("2005-04-12",detail.get("birth_date").toString());assertEquals(0L,db.count("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='student' AND column_name IN ('department_id','major_id','enrollment_year')"));}
 @Test void eachStaffRoleStoresPersonnelFieldsOutsideAuthenticationTable(){String managerNo="M-"+UUID.randomUUID(),repairerNo="R-"+UUID.randomUUID(),adminNo="A-"+UUID.randomUUID();long managerId=management.saveUser(admin,null,Map.of("account","manager-profile-"+UUID.randomUUID(),"employeeNo",managerNo,"realName","Manager Profile","gender","FEMALE","birthDate","1988-02-03","hireDate","2015-09-01","roleCode","DORM_MANAGER","password","123456"));long repairerId=management.saveUser(admin,null,Map.of("account","repair-profile-"+UUID.randomUUID(),"employeeNo",repairerNo,"realName","Repair Profile","gender","MALE","birthDate","1990-03-04","hireDate","2016-10-01","roleCode","REPAIRER","password","123456"));long adminId=management.saveUser(admin,null,Map.of("account","admin-profile-"+UUID.randomUUID(),"employeeNo",adminNo,"realName","Admin Profile","gender","OTHER","birthDate","1985-05-06","hireDate","2012-08-01","roleCode","ADMIN","password","123456"));assertEquals(1L,db.count("SELECT COUNT(*) FROM dorm_manager_profile WHERE manager_user_id=? AND employee_no=? AND hire_date='2015-09-01'",managerId,managerNo));assertEquals(1L,db.count("SELECT COUNT(*) FROM repairer_profile WHERE repairer_user_id=? AND employee_no=? AND hire_date='2016-10-01'",repairerId,repairerNo));assertEquals(1L,db.count("SELECT COUNT(*) FROM system_admin_profile WHERE admin_user_id=? AND employee_no=? AND hire_date='2012-08-01'",adminId,adminNo));assertEquals(0L,db.count("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='sys_user'"));}
