 @Test void adminUserSearchAndDetailHttpEndpoints(){try{String account="http-student-"+UUID.randomUUID();String studentNo="H"+UUID.randomUUID().toString().substring(0,20);long user=management.saveUser(admin,null,Map.of("account",account,"studentNo",studentNo,"realName","HTTP Student","gender","MALE","roleCode","STUDENT","password","123456"));String login=mvc.perform(post("/api/v1/auth/login").contentType("application/json").content("{\"loginAccount\":\"admin\",\"password\":\"123456\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String token=json.readTree(login).path("data").path("token").asText();String filtered=mvc.perform(get("/api/v1/admin/users").param("roleCode","STUDENT").param("studentNo",studentNo).param("keyword",account).header("Authorization","Bearer "+token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertEquals(studentNo,json.readTree(filtered).path("data").get(0).path("student_no").asText());String detail=mvc.perform(get("/api/v1/admin/users/"+user).header("Authorization","Bearer "+token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertEquals(studentNo,json.readTree(detail).path("data").path("student_no").asText());}catch(Exception e){throw new AssertionError(e);}}
