 @Test void urgentManualDispatchCannotBeRejected(){long id=create();repair.review(manager,id,Map.of("pass",true,"urgent",true));assertEquals("PENDING_MANUAL",state(id));repair.dispatch(manager,id,Map.of("repairerUserId",3));assertEquals("ACCEPTED",state(id));assertThrows(BizException.class,()->repair.decision(worker,id,Map.of("accept",false,"reason","No")));}
 @Test void rejectionWithoutNewCandidateStopsAutoDispatch(){long id=create();repair.review(manager,id,Map.of("pass",true));assertThrows(BizException.class,()->repair.decision(worker,id,Map.of("accept",false)));repair.decision(worker,id,Map.of("accept",false,"reason","Unavailable"));assertEquals("PENDING_MANUAL",state(id));assertEquals(1L,Input.id(order(id).get("reject_count")));assertTrue(repair.list(worker).stream().anyMatch(x->Input.id(x.get("order_id"))==id));}
 @Test void threeRefusalsMarkAbnormal(){for(int i=0;i<2;i++){long uid=management.saveUser(admin,null,Map.of("account","testworker"+i,"employeeNo","R-"+UUID.randomUUID(),"password","123456","realName","Worker","roleCode","REPAIRER"));management.worker(admin,uid,Map.of("onDuty",true,"workTypeIds",List.of(2),"buildingIds",List.of(1)));}long id=create();repair.review(manager,id,Map.of("pass",true));for(int i=0;i<3;i++){long uid=Input.id(order(id).get("repairer_user_id"));repair.decision(new CurrentUser(uid,"test","test","REPAIRER"),id,Map.of("accept",false,"reason","Unavailable"));}assertEquals("PENDING_MANUAL",state(id));assertEquals(3L,Input.id(order(id).get("reject_count")));assertTrue(Input.flag(order(id),"abnormal"));assertThrows(BizException.class,()->repair.retry(manager,id));}
 @Test void delayApprovalAndRejectionKeepCorrectDeadlines()throws Exception{long id=accepted();String original=order(id).get("repair_deadline").toString();repair.delay(worker,id,Map.of("reason","Need parts","expectedFinishAt",LocalDateTime.now().plusDays(3).toString(),"fileIds",List.of(photo(worker))));assertEquals("DELAYED",state(id));repair.reviewDelay(manager,id,Map.of("pass",false,"reason","Use available parts"));assertEquals("ACCEPTED",state(id));assertEquals(original,order(id).get("repair_deadline").toString());repair.delay(worker,id,Map.of("reason","Need parts","expectedFinishAt",LocalDateTime.now().plusDays(3).toString(),"fileIds",List.of(photo(worker))));repair.reviewDelay(manager,id,Map.of("pass",true));assertTrue(Input.time(order(id).get("repair_deadline")).isAfter(LocalDateTime.now().plusDays(2)));complete(id);}
 @Test void pendingDelayPausesTimeoutAndRejectedExpiredDelayReassigns()throws Exception{long id=accepted();repair.delay(worker,id,Map.of("reason","Parts","expectedFinishAt",LocalDateTime.now().plusDays(3).toString(),"fileIds",List.of(photo(worker))));db.update("UPDATE repair_dispatch SET repair_deadline=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE order_id=?",id);repair.tick();assertEquals("DELAYED",state(id));repair.reviewDelay(manager,id,Map.of("pass",false,"reason","Not approved"));assertEquals("PENDING_MANUAL",state(id));assertNull(order(id).get("repairer_user_id"));assertEquals(1L,Input.id(order(id).get("repair_timeout_count")));}
 @Test void reworkUsesManualAssignmentAndArchivesParent()throws Exception{long id=accepted();complete(id);long child=Input.id(repair.rework(student,id,Map.of("reason","Still broken")).get("orderId"));assertThrows(BizException.class,()->repair.confirm(student,id));repair.review(manager,child,Map.of("pass",true));assertEquals("PENDING_MANUAL",state(child));repair.dispatch(manager,child,Map.of("repairerUserId",3));complete(child);repair.confirm(student,child);assertEquals("ARCHIVED",state(id));}
 @Test void timersAreIdempotent()throws Exception{long waiting=create();repair.review(manager,waiting,Map.of("pass",true));db.update("UPDATE repair_dispatch SET accept_deadline=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE order_id=?",waiting);long repaired=accepted();complete(repaired);db.update("UPDATE repair_result SET created_at=DATE_SUB(NOW(),INTERVAL 8 DAY) WHERE order_id=?",repaired);long edit=create();repair.review(manager,edit,Map.of("pass",false,"reason","Clarify"));db.update("UPDATE repair_audit SET created_at=DATE_SUB(NOW(),INTERVAL 8 DAY) WHERE order_id=?",edit);repair.tick();repair.tick();assertEquals(1L,Input.id(order(waiting).get("accept_timeout_count")));assertEquals("ARCHIVED",state(repaired));assertEquals("CLOSED",state(edit));assertEquals(1L,db.count("SELECT COUNT(*) FROM repair_confirmation WHERE order_id=?",repaired));}
 @Test void stayLocksResubmitsAndArchives(){long b=batch();publish(b);long a=application(b);assertFalse(stay.list(manager).stream().anyMatch(x->Input.id(x.get("application_id"))==a));stay.submit(student,a);assertThrows(BizException.class,()->stay.review(manager,a,Map.of("pass",true)));stay.lock(manager,a,true);assertThrows(BizException.class,()->stay.save(student,stayBody(b)));stay.review(manager,a,Map.of("pass",false,"reason","Need details","resubmitDeadline",LocalDateTime.now().plusHours(2).toString()));application(b);assertEquals("PENDING_EDIT",stayState(a));stay.submit(student,a);assertEquals("UNDER_REVIEW",stayState(a));assertThrows(BizException.class,()->stay.review(manager,a,Map.of("pass",true)));db.update("UPDATE stay_application SET resubmit_deadline=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE application_id=?",a);stay.review(manager,a,Map.of("pass",true));db.update("UPDATE stay_date_range d JOIN stay_version v ON v.version_id=d.version_id SET d.start_date=DATE_SUB(CURRENT_DATE(),INTERVAL 2 DAY),d.end_date=DATE_SUB(CURRENT_DATE(),INTERVAL 1 DAY) WHERE v.application_id=?",a);stay.tick();assertEquals("COMPLETED",stayState(a));}
 @Test void staySharedBoundaryIsOverlap(){LocalDate d=LocalDate.now();assertThrows(BizException.class,()->StayService.validateRanges(List.of(Map.of("startDate",d.toString(),"endDate",d.plusDays(2).toString()),Map.of("startDate",d.plusDays(2).toString(),"endDate",d.plusDays(3).toString())),d,d.plusDays(5)));}
 @Test void unsubmittedEditsAreNotReviewed(){long b=batch();publish(b);long a=application(b);stay.submit(student,a);var edit=new HashMap<>(stayBody(b));edit.put("reason","Unsubmitted draft");stay.save(student,edit);assertEquals("Study",stay.list(manager).stream().filter(x->Input.id(x.get("application_id"))==a).findFirst().orElseThrow().get("reason"));stay.lock(manager,a,true);stay.review(manager,a,Map.of("pass",true));assertEquals("Study",stay.list(student).stream().filter(x->Input.id(x.get("application_id"))==a).findFirst().orElseThrow().get("reason"));}
 @Test void stayAutomaticLockAndExpiredReturn(){long b=batch();publish(b);long a=application(b);stay.submit(student,a);db.update("UPDATE stay_building_rule SET application_deadline=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE batch_id=?",b);stay.tick();assertEquals("UNDER_REVIEW",stayState(a));assertThrows(BizException.class,()->stay.lock(manager,a,false));stay.review(manager,a,Map.of("pass",false,"reason","Incomplete","resubmitDeadline",LocalDateTime.now().plusHours(1).toString()));db.update("UPDATE stay_application SET resubmit_deadline=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE application_id=?",a);stay.tick();assertEquals("ARCHIVED",stayState(a));assertEquals("未按期重新提交",db.one("SELECT archive_reason FROM stay_application WHERE application_id=?",a).get("archive_reason"));}
  @Test void studentAndBuildingIsolation(){long id=create();long other=management.saveUser(admin,null,Map.of("account","other","studentNo","T"+UUID.randomUUID().toString().substring(0,20),"realName","Other","gender","OTHER","roleCode","STUDENT","password","123456"));var user=new CurrentUser(other,"other","Other","STUDENT");assertEquals(403,assertThrows(BizException.class,()->repair.detail(user,id)).status());long mgr=management.saveUser(admin,null,Map.of("account","othermanager","employeeNo","M-"+UUID.randomUUID(),"realName","Other","roleCode","DORM_MANAGER","password","123456"));management.managerScope(admin,mgr,Map.of("buildingId",2));var m=new CurrentUser(mgr,"othermanager","Other","DORM_MANAGER");assertTrue(repair.list(m).isEmpty());assertEquals(403,assertThrows(BizException.class,()->repair.review(m,id,Map.of("pass",true))).status());assertEquals(403,assertThrows(BizException.class,()->files.get(user,photo(student))).status());}
 @Test void loginLogoutAndHttpStatus()throws Exception{String login=mvc.perform(post("/api/v1/auth/login").contentType("application/json").content("{\"loginAccount\":\"student1\",\"password\":\"123456\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String token=json.readTree(login).path("data").path("token").asText();mvc.perform(get("/api/v1/admin/users").header("Authorization","Bearer "+token)).andExpect(status().isForbidden());mvc.perform(post("/api/v1/auth/logout").header("Authorization","Bearer "+token)).andExpect(status().isOk());mvc.perform(get("/api/v1/auth/me").header("Authorization","Bearer "+token)).andExpect(status().isUnauthorized());mvc.perform(post("/api/v1/auth/login").contentType("application/json").content("{}")).andExpect(status().isBadRequest());}
